function getPartitionContent(node, tokens) {
  const preset = node.preset || {};
  const systemId = node.systemId || preset.systemId || tokens.find(token => Object.hasOwn(partitionSystems, token));
  const source = partitionSystems[systemId] || content.partitions;
  const result = { heading: node.title || 'Стеклянные перегородки', description: source.description,
    considerations: source.considerations.map(entry => ({ ...entry })), faq: source.faq.map(entry => ({ ...entry })) };
  const modelKind = node.modelKind || preset.modelKind;
  const optionKind = modelKind && modelKind !== 'configuration' ? modelKind
    : tokens.includes('glass') || node.id === 'glass' ? 'glass-option'
      : tokens.includes('decor') || tokens.includes('frame') || ['decor', 'frame'].includes(node.id) ? 'decor-option'
        : tokens.some(token => ['blinds', 'control', 'control-zones', 'segmented'].includes(token)) || ['blinds', 'control', 'control-zones', 'segmented'].includes(node.id) ? 'privacy-option' : '';
  const glazingPath = tokens[tokens.indexOf('framed') + 1];
  const glazingId = node.glazingId || preset.glazingId || (systemId === 'framed'
    ? ['double', 'clamped-double'].includes(glazingPath) ? 'double' : glazingPath === 'single' ? 'single' : '' : '');
  const treatmentId = node.glassTreatmentId || preset.glassTreatmentId || tokens.find(token => ['annealed', 'tempered', 'laminated', 'laminated-tempered'].includes(token));

  if (systemId === 'framed' && glazingId === 'double') {
    result.description = 'Два независимых ряда стекла располагаются в согласованной профильной системе. Дверной узел, стыки и пространство между рядами прорабатываются отдельно от состава каждого стекла.';
    result.considerations[0] = item('Состав каждого ряда', 'Два ряда остекления не задают автоматически состав каждой панели. Вид стекла, обработку и возможное размещение жалюзи согласуем для выбранного профиля.');
  } else if (systemId === 'framed' && glazingId === 'single') {
    result.description = 'Один ряд стеклянного заполнения удерживается каркасом. Деление на секции, дверь, фрамугу и возможные навесные жалюзи рассматриваем вместе с выбранным профилем.';
  }

  if (optionKind) {
    const scope = optionKind === 'glass-option' ? 'Это выбор стеклянного заполнения и его обработки для совместимой конструкции.'
      : optionKind === 'decor-option' ? 'Это выбор оформления или параметров каркаса для совместимой стеклянной конструкции.'
        : 'Это выбор приватности или управления для совместимой стеклянной конструкции.';
    result.description = [node.intro, scope, systemId === 'smart' ? source.description : 'Геометрию, состав секций и открывание согласуем отдельно.'].filter(Boolean).join(' ');
    if (systemId !== 'smart') {
      result.considerations = [
        item('Содержание выбора', scope + ' Карточка помогает зафиксировать пожелание к проекту.'),
        item('Образец и размещение', optionKind === 'decor-option' ? 'Рисунок, деления и отделку оцениваем на образце и развёртке с учётом стыков, ручек и видимых границ.' : 'Проверьте цвет, фактуру и видимость в освещении помещения. Для жалюзи отдельно задайте расположение и доступ к управлению.'),
        item('Совместимость с системой', 'Размеры, состав стекла и крепления проверяются для выбранной конструкции. Отдельный вариант заполнения не определяет дверной механизм.'),
      ];
    }
    result.faq.unshift(qa('Эта карточка определяет всю перегородку?', 'Она описывает отдельный вариант комплектации. Для заказа связываем его с выбранной конструкцией, размерами, открыванием и узлами крепления.'));
  } else {
    const openingId = node.openingId || preset.openingId || [...tokens].reverse().find(token => Object.hasOwn(partitionOpenings, token));
    const opening = partitionOpenings[openingId];
    if (opening) {
      result.description += ' ' + opening.description;
      if (systemId === 'smart') {
        result.considerations[2] = item('Движение и питание', opening.consideration.text + ' Переключение видимости работает отдельно от движения. Контроллер, подвод и передачу питания согласуем с механизмом.');
        result.faq.push(opening.faq);
      } else {
        result.considerations[1] = { ...opening.consideration };
        result.faq[1] = { ...opening.faq };
      }
    }
  }

  if (systemId === 'smart' && (preset.controlZonesId || tokens.includes('control-zones') || node.id === 'control-zones')) {
    result.considerations[2] = item('Группы и каналы управления', 'Определите, какие целые панели переключаются вместе, а какие независимо. Группировку, каналы контроллера, подвод питания и доступ для обслуживания согласуем на электрической схеме.');
    result.faq.push(qa('Независимые панели и сегменты внутри стекла — одно и то же?', 'Здесь управляемая зона — целая панель или группа панелей. Полосы и участки внутри одного стекла относятся к сегментированному переключаемому слою и выбираются отдельно.'));
  } else if (systemId === 'smart' && (preset.segmentationId || tokens.includes('segmented') || node.id === 'segmented')) {
    result.considerations[2] = item('Рисунок переключаемых зон', 'Полосы и участки задаются внутри переключаемого слоя одной панели. Их границы, контакты, питание и управление согласуются до изготовления триплекса.');
    result.faq.push(qa('Сегментация означает управление отдельными стёклами?', 'Она задаёт переключаемые участки внутри одной панели. Независимое управление целыми стёклами или группами панелей — отдельная электрическая схема.'));
  }
  if (systemId !== 'smart' && treatmentId === 'annealed') {
    result.considerations[2] = item('Применимость незакалённого стекла', 'Такое заполнение рассматриваем только по согласованию для неподвижного стекла в удерживающей раме. Применение в двери или безрамной секции автоматически не предполагается.');
    result.faq.push(qa('Можно выбрать незакалённое стекло для любой секции?', 'Применимость проверяется отдельно по назначению, размерам, удержанию стекла и выбранной системе. Указанная в карточке толщина остаётся запросом до согласования.'));
  } else if (systemId !== 'smart' && ['laminated', 'laminated-tempered'].includes(treatmentId)) {
    result.considerations[2] = item('Состав многослойной панели', 'В триплексе листы соединены прослойкой. Число и обработку листов, межслой и итоговый состав выбирают под опоры; два независимых ряда остекления — другой параметр конструкции.');
  } else if (systemId !== 'smart' && treatmentId === 'tempered') {
    result.considerations[2] = item('Толщина и подготовка', 'Толщину проверяют по размерам, опиранию и механизму. Контур, отверстия, вырезы и обработку кромок согласуют до закалки.');
  }
  if (systemId === 'framed' && optionKind === 'privacy-option') {
    result.considerations[2] = preset.blindsId === 'between-panes'
      ? item('Межрамное размещение', 'Жалюзи располагаются между двумя независимыми рядами стекла. Место механизма, наружное управление и доступ для обслуживания согласуются с профилем.')
      : preset.blindsId === 'external'
        ? item('Навесное размещение', 'При одинарном стекле жалюзи размещаются отдельно со стороны помещения. Проверяем крепление, доступ к стеклу и место для управления.')
        : item('Место жалюзи', 'Навесное размещение при одинарном стекле и межрамное при двух рядах — разные исполнения. Выберите подходящий вариант, затем согласуйте управление и обслуживание.');
  }
  return result;
}

function identify(node) {
  const path = String(node?.path || node?.url || '').replace(/^#/, '');
  const tokens = path.split('/').filter(Boolean);
  const id = String(node?.id || '');
  const solution = String(node?.solutionId || '');
  const category = node?.category || tokens[tokens.indexOf('catalog') + 1] ||
    ['mirrors', 'showers', 'partitions', 'doors', 'stairs', 'canopies'].find(key => id === key || id.startsWith(key + '-')) ||
    (/^mirror-/.test(solution) ? 'mirrors' : /^shower-|^bath-/.test(solution) ? 'showers' : /^partition-/.test(solution) ? 'partitions' : /^door-/.test(solution) ? 'doors' : /^stairs-|^railing-/.test(solution) ? 'stairs' : /^canopy-/.test(solution) ? 'canopies' : 'mirrors');
  const families = ['with-light', 'framed', 'frameless', 'panels', 'architecture', 'pivot', 'smart', 'decorative'];
  let family = families.find(key => tokens.includes(key)) || families.find(key => key === id);
  if (!family && category === 'mirrors') {
    if (/mirror-lighting|mirror-dressing/.test(solution) || node?.preset?.lighting && !/по проекту/i.test(node.preset.lighting)) family = 'with-light';
    else if (/mirror-pivot/.test(solution)) family = 'pivot';
    else if (/mirror-smart/.test(solution)) family = 'smart';
    else if (/mirror-panel/.test(solution)) family = 'panels';
    else if (/mirror-aged/.test(solution) || node?.preset?.mirrorColor) family = 'decorative';
    else if (/mirror-.*frame/.test(solution)) family = 'framed';
    else if (/mirror-wall|mirror-ceiling|mirror-door/.test(solution)) family = 'architecture';
    else if (node?.preset?.frame === 'Без рамы') family = 'frameless';
  }
  const haystack = [path, id, solution, node?.preset?.application, node?.preset?.opening, node?.preset?.mounting].filter(Boolean).join(' ').toLowerCase();
  const key = category === 'mirrors' ? family === 'with-light' ? 'lighting' : family || 'mirrors' : category === 'showers' && /bath|баня/.test(haystack) ? 'bath' : category;
  return { key, haystack, path, tokens };
}

export function getPageContent(node = {}) {
  const { key, haystack, tokens } = identify(node);
  if (key === 'partitions' || !node.category && Object.hasOwn(partitionSystems, node.systemId || node.preset?.systemId || '')) {
    return getPartitionContent(node, tokens);
  }
  const source = content[key] || content.mirrors;
  const result = {
    heading: node.title || 'Стекло и зеркала для вашего пространства',
    description: source.description,
    considerations: source.considerations.map(entry => ({ ...entry })),
    faq: source.faq.map(entry => ({ ...entry })),
  };

  if (key === 'lighting' && tokens.includes('contour')) {
    result.description = 'Свет за зеркалом мягко выделяет силуэт на стене. Форма, отступ от основания и фактура отделки вместе определяют, как будет восприниматься световой контур.';
  } else if (key === 'lighting' && tokens.includes('front')) {
    result.description = 'Фронтальная световая зона становится частью зеркальной плоскости. Её рисунок и положение подбираем под пропорции зеркала и ваш сценарий использования.';
  } else if (key === 'lighting' && tokens.includes('combined')) {
    result.description = 'Лицевой свет и мягкий контур за зеркалом работают на разных планах. Их сочетание прорабатываем вместе с формой, подключением и общим освещением комнаты.';
  } else if (key === 'lighting' && tokens.includes('dressing')) {
    result.description = 'Гримёрное зеркало связывает отражение со светом для работы с образом. Расположение световых зон выбираем для туалетного столика, рабочего места или ростовой композиции.';
  }

  if (key === 'architecture' && /ceilings|mirror-ceiling/.test(haystack)) {
    result.considerations[2] = item('Потолочная установка', 'Основание и система удержания рассматриваются отдельно для потолка. Предусматриваем положение светильников, стыков и доступ к соседним коммуникациям.');
  }
  if (key === 'architecture' && /mirror-door|\/architecture\/doors/.test(haystack)) {
    result.considerations[2] = item('Дверная система', 'Зеркальную поверхность согласуем с основой дверного полотна и механизмом открывания. Если система уже выбрана, приложите её документацию.');
  }
  if (key === 'showers' && /sliding|раздвиж/.test(haystack) || key === 'doors' && /sliding|раздвиж/.test(haystack)) {
    result.considerations[0] = item('Место для перемещения', 'Проверьте, куда будет уходить створка и какая ширина прохода останется открытой. Рядом с траекторией не должно быть мешающих ручек, мебели или выступов.');
  }
  if (key === 'showers' && /showers-open|corner-open|fixed-screen/.test(haystack)) {
    result.description = 'Стационарный экран отделяет душевую зону, оставляя открытый вход. Длину стекла и положение прохода выбираем с учётом душевой лейки, планировки и направления воды. ' + glass;
  }
  if (key === 'showers' && /showers-tub/.test(haystack)) {
    result.description = 'Стеклянная шторка ставится на борт ванны и ограничивает разбрызгивание. Выберите неподвижный экран, поворотную створку, складную или раздвижную композицию. ' + glass;
    result.considerations[0] = item('Борт и опора', 'Нужны материал ванны, форма и ширина её борта. Крепление к стене и опору стекла подбираем с учётом конкретной ванны.');
    result.faq[0] = qa('Можно поставить шторку на мою ванну?', 'Для проверки пришлите фотографии, размеры и модель ванны. Важны форма борта, положение смесителя и возможность надёжно закрепить стекло у стены.');
    result.faq[1] = qa('Как открывать экран для уборки?', 'Поворотные и складные секции дают доступ к ванне. У стационарного экрана заранее проверяем доступ с обеих сторон; направление движения согласуем по плану ванной.');
  } else if (key === 'showers' && /folding|склад/.test(haystack)) {
    result.description = 'Складная дверь собирается из связанных створок и помогает организовать вход в ограниченном пространстве. Проверяем положение пакета стёкол и свободный проход.';
    result.considerations[0] = item('Место для складывания', 'Сложенные полотна тоже занимают место. Отмечаем смеситель, лейку, полки и соседнюю мебель, чтобы выбрать направление складывания.');
    result.faq[0] = qa('В какую сторону складывается дверь?', 'Направление зависит от системы и планировки. Его согласуем по чертежу с учётом прохода и оборудования внутри душа.');
  } else if (key === 'showers' && /showers-trapezoid/.test(haystack)) {
    result.description = 'Скошенная входная сторона формирует пятиугольное ограждение или полутрапецию. Положение двери выбираем относительно боковых стёкол и стен.';
    result.faq[0] = qa('Как выбрать форму трапеции?', 'Нужен план с длинами сторон и фактическими углами. Полная трапеция и полутрапеция отличаются количеством боковых плоскостей и опорой дверной фурнитуры.');
  } else if (key === 'showers' && /showers-custom/.test(haystack)) {
    result.description = 'Скос, выступ, вырез или кривизна задают индивидуальную геометрию остекления. До изготовления согласуем контур, состав стекла и расположение опор.';
    result.faq[0] = qa('Достаточно приблизительных размеров?', 'Их достаточно для первого обсуждения. Для изготовления нужны согласованный чертёж и чистовые размеры; сложный контур может потребовать шаблона.');
  }
  if (key === 'stairs' && /glass-steps|steps-parts/.test(haystack)) {
    result.description = 'Стеклянные ступени изготавливаются как детали для конкретного лестничного проекта. Геометрию, состав и обработку согласуем вместе со схемой опирания и требованиями к поверхности. ' + glass;
  } else if (key === 'stairs' && /railings|railing-/.test(haystack)) {
    result.description = 'Стеклянное ограждение сохраняет обзор лестницы, площадки или открытого края перекрытия. Крепление и деление на полотна выбираем по основанию, геометрии и желаемой линии поручня. ' + glass;
  }
  if (key === 'canopies' && /profile|профиль/.test(haystack)) {
    result.considerations[1] = item('Линия зажимного профиля', 'Профиль проходит вдоль стены, поэтому особенно важны материал основания, его геометрия и толщина фасадной отделки. Эти данные нужны для подбора системы.');
  } else if (key === 'canopies' && /rods|тяги|ванты/.test(haystack)) {
    result.considerations[1] = item('Положение тяг', 'Тяги становятся частью рисунка фасада. Заранее отмечаем места верхних креплений, соседние окна и доступную высоту над входом.');
  }
  return result;
}
